(974, 12, 410, 973, '¡Allí estaré!', '2025-09-30'),
(975, 45, 410, 974, '¿Jugarás con seguidores?', '2025-10-01'),
(976, 230, 410, 975, 'Probablemente en la segunda mitad.', '2025-10-01'),
